def roman_numeral(n):
    values = [
        (1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'),
        (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'),
        (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'), (1, 'I'),
    ]
    parts = []
    remaining = n
    for value, symbol in values:
        count, remaining = divmod(remaining, value)
        parts.append(symbol * count)
    return ''.join(parts)

def reorder_by_priority_list(items, priority):
    rank = {val: idx for idx, val in enumerate(priority)}
    in_priority = [it for it in items if it in rank]
    rest = [it for it in items if it not in rank]
    in_priority.sort(key=lambda it: rank[it])
    return in_priority + rest

