def is_valid_pin_code(s):
    if len(s) != 4 or not s.isdigit():
        return False
    d = [int(c) for c in s]
    if d[0] == d[1] == d[2] == d[3]:
        return False
    ascending = all(d[i] + 1 == d[i + 1] for i in range(3))
    descending = all(d[i] - 1 == d[i + 1] for i in range(3))
    if ascending or descending:
        return False
    return True

