def sum_of_first_n_primes(n):
    def is_prime(x):
        if x < 2:
            return False
        if x < 4:
            return True
        if x % 2 == 0:
            return False
        i = 3
        while i * i <= x:
            if x % i == 0:
                return False
            i += 2
        return True
    found = 0
    total = 0
    candidate = 1
    while found < n:
        candidate += 1
        if is_prime(candidate):
            total += candidate
            found += 1
    return total

def min_max_across_dicts(records):
