def common_dedent(lines):
    non_blank = [ln for ln in lines if ln.strip() != '']
    if not non_blank:
        return list(lines)
    indent = min(len(ln) - len(ln.lstrip(' ')) for ln in non_blank)
    return [ln[indent:] if ln.strip() != '' else ln for ln in lines]

